import org.junit.jupiter.api.Test;

class WholeRowObservationTest {
	@Test
	void wholeRowIdentityCannotHaveACompleteFiniteVarOnlyObservationDomain() {
		assertAll(
				() -> assertUnknownWholeRowDomain("INTERSECT",
						new Intersection(new SingletonSet(), emptyProjection())),
				() -> assertUnknownWholeRowDomain("DISTINCT", new Slice(new Distinct(unequalInputShapes()), 1, 1)),
				() -> assertUnknownWholeRowDomain("REDUCED", new Slice(new Reduced(unequalInputShapes()), 1, 1)),
				() -> assertUnknownWholeRowDomain("COUNT(DISTINCT *)",
						new Group(unequalInputShapes(), Set.of(),
								List.of(new GroupElem("count", new Count(null, true))))));
	}

	private static void assertUnknownWholeRowDomain(String label, TupleExpr body) {
		TupleExprs.ConditionBindingDomain direct = TupleExprs.tupleBindingObservationDomain(body);
		assertThat(direct.known()).as("%s compares complete mappings with arbitrary incoming names", label).isFalse();
		assertThat(TupleExprs.conditionBindingDomain(new Exists(body.clone())).known()).isFalse();
		assertThat(TupleExprs.conditionBindingDomain(new Not(new Exists(body.clone()))).known()).isFalse();
		assertThat(TupleExprs.conditionBindingDomain(new Exists(
				new Filter(new SingletonSet(), new Not(new Exists(body.clone()))))).known()).isFalse();
	}

	@Test
	void unvaluedConstantFlagDoesNotProveThatVarOrBoundIgnoresItsName() {
		Var input = Var.of("input", null, false, true);
		assertThat(input.isConstant()).isTrue();
		assertThat(input.hasValue()).isFalse();
		for (var condition : List.of(input, new Bound(input.clone()))) {
			TupleExprs.ConditionBindingDomain domain = TupleExprs.conditionBindingDomain(condition);
			assertThat(!domain.known() || domain.names().contains("input")).isTrue();
			assertThat(TupleExprs.conditionFrameContainsAllObservations(domain, Set.of())).isFalse();
		}
	}

	@Test
	void valuedConstantDoesNotAddAnOrdinaryInputDependency() {
		Var fixed = Var.of("input", SimpleValueFactory.getInstance().createLiteral(2), false, true);
		for (var condition : List.of(fixed, new Bound(fixed.clone()))) {
			TupleExprs.ConditionBindingDomain domain = TupleExprs.conditionBindingDomain(condition);
			assertThat(domain.known()).isTrue();
			assertThat(domain.names()).isEmpty();
		}
	}

	private static Projection emptyProjection() {
		// An ordinary projection removes the mapping; a nested SELECT would rejoin compatibility inputs.
		return new Projection(new SingletonSet(), new ProjectionElemList(), false);
	}

	private static Union unequalInputShapes() {
		return new Union(new SingletonSet(), emptyProjection());
	}
}
